// Pre-normalized 1-bit monochrome vector courier marks (absolute M/L/C/Z commands in a 100-unit width box)
// derived from apps/web-app/public/couriers/*.svg so both PDF (203 dpi thermal) and SVG previews render identical logos.
export interface VectorPath {
  d: string
  evenOdd?: boolean
  white?: boolean
}
export interface CourierMark {
  w: number
  h: number
  paths: VectorPath[]
}

const KEYS = ["jne", "jt", "sicepat", "sap", "lion", "anteraja", "idexpress", "pos", "spx"] as const
export type CourierMarkKey = (typeof KEYS)[number]

export function courierMarkKey(value: string | null | undefined): CourierMarkKey | null {
  const s = (value ?? "").toLowerCase().replace(/[^a-z0-9]/g, "")
  return KEYS.find((k) => s.startsWith(k)) ?? null
}

